    "centre_of_mass": "Centre of mass",
    "up_to_four_masses": "Up to four masses at points (x, y): where their centre of mass is, as of a seesaw or a molecule, drawn; the mass in all, and their moment of inertia about the centre and about 0. x and y are 0 unless typed: leave y empty along a line.",
    "force_mass_and_acceleration": "Force, mass and acceleration",
    "newton_s_second_law": "Newton's second law: type two of F, m and a and the third is worked out; and the weight of the mass.",
    "inclined_plane": "Inclined plane",
    "mass_on_slope_of": "A mass on a slope of angle θ with friction μ: its weight, the normal force, the force along the slope, the friction and the acceleration, and whether it slides.",
    "masses_over_pulley": "Masses over a pulley",
    "two_masses_on_string": "Two masses on a string over a pulley, m<sub>1</sub> hanging and m<sub>2</sub> hanging too, as Atwood's machine, on a table, or on a slope of angle θ, with friction μ: their acceleration, which way they go, the tension in the string, and whether friction holds them; drawn. With a distance d, how fast they go after it and how long it takes. With the pulley's mass, a disc, it turns too.",
    "two_hanging": "Two hanging",
