    "bounce_elastic": "Bounce, elastic",
    "stick_together": "Stick together",
    "impulse_and_momentum": "Impulse and momentum",
    "mass_whose_speed_changes": "A mass whose speed changes from u to v, below 0 the other way: its momentum before and after, the impulse that changed it, and in a time Δt the average force, as of a bat on a ball or a crumple zone.",
    "kinetic_and_potential_energy": "Kinetic and potential energy",
    "kinetic_energy_of_mass": "The kinetic energy of a mass at a speed, its potential energy at a height, and the speed it would have at the ground, falling with no air.",
    "work_and_power": "Work and power",
    "work_of_force_along": "The work of a force along a way, at an angle θ to it, and the power of it done in a time.",
    "torque_and_levers": "Torque and levers",
    "turning_of_force_f": "The turning of a force F pushing r from a pivot, at θ to the bar, a right angle unless typed; or a lever balanced, of a load and its distance from the pivot: the effort at another distance, and how much it gives.",
    "force": "A force",
    "lever": "A lever",
    "d_load": "d load",
    "d_effort": "d effort",
    "gravitation": "Gravitation",
    "pull_between_two_masses": "The pull between two masses r apart, by Newton's law; and of the first, as a planet, the gravity at r, the speed and period of a circular orbit, the escape speed, and the radius it would be a black hole within, Schwarzschild's. The Earth is 5.972e24 kg, its radius 6.371e6 m; the Sun 1.989e30 kg.",
    "spring_of_stiffness_k": "A spring of stiffness k stretched or squeezed by x, by Hooke's law: its force and the energy it holds; with a mass, its period.",
    "drag_and_terminal_velocity": "Drag and terminal velocity",
    "mass_falling_through_air": "A mass falling through air: the speed it falls no faster than, where drag is its weight, how long it takes to reach 95% of it and how far it falls till then; and the drag at a speed. C<sub>d</sub> of a ball is about 0.47, a person falling 1, a car 0.3. Air is 1.225 kg/m³.",
    "cd": "Cd",
    "coulomb_s_law": "Coulomb's law",
    "force_between_two_charges": "The force between two charges r apart, whether they pull or push, the field and the potential of the first at the second, and the energy of the two. Charges as 2µ or 1.6e-19; k = 8.988 × 10⁹ N·m²/C².",
    "magnetic_force": "Magnetic force",
    "force_of_magnetic_field": "The force of a magnetic field B on a charge moving through it, with the circle it goes round, its period and frequency, an electron's unless typed; or on a wire carrying a current. θ between them, a right angle unless typed.",
    "on": "On",
    "charge": "A charge",
    "wire": "A wire",
    "teslas": "teslas",
    "magnetic_field": "Magnetic field",
    "field_of_current_at": "The field of a current: at r from a long straight wire, and of a second wire there carrying I₂, the force between them each metre; inside a solenoid of N turns along L, its core μ<sub>r</sub> times stronger; or at the middle of a loop of radius r and N turns. The Earth's is about 50 µT.",
    "solenoid": "A solenoid",
    "loop": "A loop",
    "induction": "Induction",
    "voltage_changing_field_makes": "The voltage a changing field makes, by Faraday's law: in a coil of N turns and area A, its field changing by ΔB in Δt; in a rod of length L moving at v across a field; or the peak of a generator, its coil turning at so many revolutions a minute. With a resistance, the current.",
    "coil": "A coil",
    "moving_rod": "A moving rod",
    "generator": "A generator",
    "optional_3": "Ω, optional",
    "waves": "Waves",
    "type_two_of_speed": "Type two of the speed v, the frequency f and the wavelength λ, and the third is worked out; and the period, angular frequency and wave number.",
    "hz": "Hz",
    "standing_waves": "Standing waves",
    "string_held_at_both": "A string held at both ends, as a guitar's, of tension T and mass a metre μ; or a pipe open at both ends, or closed at one, as a flute or a clarinet: the frequency of its n-th mode, its wavelength, and its nodes, drawn. Sound in air at 20 °C goes 343 m/s.",
    "string": "A string",
    "open_pipe": "An open pipe",
    "closed_pipe": "A closed pipe",
    "kg_m_2": "kg/m",
    "beats": "Beats",
    "two_notes_of_frequencies": "Two notes of frequencies near each other sounded together: their loudness rising and falling, the beats, how many a second and how long between them, the note heard, between the two, and how far apart they are in cents; drawn. As a string is tuned to another, the beats slow till there are none.",
    "hz_440": "Hz, 440",
    "hz_444": "Hz, 444",
    "lenses_and_mirrors": "Lenses and mirrors",
    "thin_lens_or_mirror": "A thin lens or a mirror: type two of the focal length f, the distance to the object and to the image, and the third is worked out; the magnification, and the image. f is above 0 for a converging lens or a concave mirror; an image distance below 0 is virtual.",
    "lensmaker_s_equation": "Lensmaker's equation",
    "thin_lens_of_index": "A thin lens of index n, of faces of radii R<sub>1</sub>, the one the light meets first, and R<sub>2</sub>: its focal length, its power in dioptres, and whether it gathers light or spreads it; its shape drawn. A radius is above 0 where its centre is past its face, so a lens bulging both ways has R<sub>1</sub> above 0 and R<sub>2</sub> below; empty, the face is flat. Glass is about 1.5; in water, n<sub>m</sub> is 1.333.",
    "m_empty_flat": "m, empty flat",
    "refraction": "Refraction",
    "light_going_from_one": "Light going from one medium to another, by Snell's law: the angle it bends to, from the normal, the critical angle, and whether it is all reflected. Air is 1.000293, water 1.333, glass about 1.5.",
    "interference": "Interference",
    "light_through_two_slits": "Light through two slits a gap d apart, onto a screen L away: how far apart its bright fringes are, by Young; or through a grating of so many lines a millimetre: the angle of each order, and how many there are. Drawn in its colour.",
    "through": "Through",
    "two_slits": "Two slits",
    "grating": "A grating",
    "nm": "λ, nm",
    "lines_mm": "Lines/mm",
    "order": "Order",
    "one_slit_and_resolution": "One slit and resolution",
    "light_through_one_slit": "Light through one slit of width a: the angle of its m-th dark fringe, how wide the bright middle is, and on a screen L away, in metres too. Or through a round hole of width D, as of a telescope, a camera or the eye: the smallest angle between two points it tells apart, by Rayleigh, and at a distance, how far apart they must be. The eye's pupil is some 2 to 8 mm. The light drawn in its colour.",
    "slit": "A slit",
    "round_hole": "A round hole",
    "polarisation": "Polarisation",
    "polarised_light_through_polariser": "Polarised light through a polariser at θ to it: what goes through, by Malus's law, and of light not polarised, through one first; and of light off a surface from n₁ into n₂, the angle where what it reflects is all polarised, Brewster's.",
    "doppler_effect": "Doppler effect",
    "frequency_heard_of_source": "The frequency heard of a source moving and a listener moving: speeds above 0 toward each other, below 0 apart. Sound in air at 20 °C goes 343 m/s. Or light, of a star or a galaxy going away at v, by relativity: its wavelength seen, longer, redder, and its redshift z; below 0 coming nearer, bluer. Hydrogen's red line, Hα, is 656.3 nm.",
    "sound": "Sound",
