    "l_db": "L, dB",
    "specific_heat": "Specific heat",
    "heat_to_warm_mass": "The heat to warm a mass by ΔT, or that it gives cooling: type three of the heat Q, the mass m, the specific heat c and ΔT, and the fourth is worked out. Water is 4186 J/(kg·K), ice 2100, aluminium 900, iron 450, copper 385.",
    "j_kg_k": "J/(kg·K)",
    "k_or_c": "K or °C",
    "latent_heat": "Latent heat",
    "heat_to_melt_or": "The heat to melt or boil a mass, its temperature staying the same: type two of the heat Q, the mass m and the latent heat L, and the third is worked out. Ice melts at 334 kJ/kg, 3.34e5; water boils at 2.26 MJ/kg, 2.26e6.",
    "j_kg": "J/kg",
    "mixing": "Mixing",
    "two_things_at_two": "Two things at two temperatures put together, as hot water into cold: the temperature they end at, and the heat that goes from one to the other. c is water's, 4186, unless typed.",
    "thermal_expansion": "Thermal expansion",
    "how_much_longer_or": "How much longer, or larger, a thing grows warmed by ΔT, smaller cooled. Steel is about 12e-6 per K, aluminium 23e-6, glass 9e-6; of a solid, β is about 3α.",
    "heat_conduction": "Heat conduction",
    "heat_flows_each_second": "The heat that flows each second through a wall or a pane of thickness d and area A, by Fourier's law, with ΔT across it. k of copper is about 400 W/(m·K), glass 0.8, brick 0.7, wood 0.15, air 0.026.",
    "radiation": "Radiation",
    "power_hot_body_shines": "The power a hot body shines, by the Stefan–Boltzmann law, and the wavelength it shines brightest at, by Wien's; with the temperature around it, what it loses. Temperatures in kelvin: the Sun is 5772 K, a person 310.",
    "around": "Around",
    "k_optional": "K, optional",
    "cooling": "Cooling",
    "newton_s_law_of": "Newton's law of cooling: a thing at T<sub>0</sub> in air at T<sub>a</sub>, as a cup of tea, cooling, or warming, the faster the farther it is from the air. Of its k a minute, or of a reading, T<sub>1</sub> after t<sub>1</sub> minutes: its temperature after t minutes, how long it takes to come to a temperature, and its curve. In °C, or any one unit.",
    "reading": "A reading",
    "c_at_first": "°C, at first",
