    "min_optional": "min, optional",
    "dew_point_and_humidity": "Dew point and humidity",
    "air_at_temperature_t": "Air at a temperature T and a relative humidity RH: its dew point, where water comes out of it as it cools, as dew, mist or on a cold glass; or of its dew point, its humidity. The water in a cubic metre of it, and the pressure of its vapour, drawn on the curve of the most air holds. By Magnus's formula, b 17.625 and c 243.04 °C, from –45 °C to 60 °C. In °C.",
    "humidity": "Humidity",
    "dew_point": "Dew point",
    "td": "Td",
    "rh": "RH",
    "gas_molecules": "Gas molecules",
    "molecules_of_gas_of": "The molecules of a gas of molar mass M at a temperature T, by the kinetic theory: how fast they go, the root mean square, the mean and the most likely speed, drawn; and the energy of each. M in g/mol: air is about 29, nitrogen 28, oxygen 32, helium 4. T in kelvin.",
    "g_mol_2": "g/mol",
    "gas_processes": "Gas processes",
    "ideal_gas_at_p": "An ideal gas at P₁, V₁ and T₁ taken to a new volume at a steady temperature, isothermal, at a steady pressure, isobaric, or with no heat in or out, adiabatic; or warmed at a steady volume, isochoric, to a new temperature: its pressure, volume and temperature after, how many moles, the work it does, the heat put in and the change in its energy, its path drawn. Air is of two atoms a molecule, γ 7/5; helium and argon of one, 5/3. T in kelvin.",
    "isothermal": "Isothermal",
