    "engine_between_hot_t": "An engine between a hot T<sub>H</sub> and a cold T<sub>C</sub>, in kelvin: the most of its heat it can turn to work, Carnot's; with the heat taken in and the work done, how well it does. Or a fridge or a heat pump: the most heat it can move for each joule.",
