    "stress_and_strain": "Stress and strain",
    "wire_or_bar_of": "A wire or bar of length L and cross-section A pulled by a force F: its stress, and of how much it stretches, ΔL, or of its Young's modulus E, the other; its strain and the energy it holds. Steel is about 200 GPa, 200G; copper 120G, aluminium 70G, rubber 0.01G to 0.1G.",
    "pa_as_200g": "Pa, as 200G",
    "density": "Density",
    "type_two_of_density": "Type two of the density ρ, the mass m and the volume V, and the third is worked out; and whether it floats on water. Water is 1000 kg/m³, ice 917, aluminium 2700, iron 7870, gold 19300.",
    "kg_m": "kg/m³",
    "pressure": "Pressure",
    "type_two_of_pressure": "Type two of the pressure P, the force F and the area A it pushes on, and the third is worked out; the pressure in other units too.",
    "pa": "Pa",
    "pressure_at_depth": "Pressure at a depth",
    "pressure_at_depth_h": "The pressure at a depth h in a liquid: of the liquid alone, gauge, and with the air above, absolute; with an area, the force on it. Water unless typed, 1000 kg/m³; sea water is 1025.",
    "m_optional_2": "m², optional",
    "buoyancy": "Buoyancy",
    "thing_of_mass_m": "A thing of mass m and volume V in a liquid, by Archimedes' principle: the push up on it all under, whether it floats, how much of it is under, and how heavy it seems under. Water unless typed.",
    "fluid": "ρ fluid",
    "flow_in_pipe": "Flow in a pipe",
    "liquid_flowing_from_pipe": "A liquid flowing from a pipe of one width into another, by continuity and Bernoulli's law, with no friction: its speed in the second, the flow, and how much its pressure falls; with a rise in height, of that too. Water unless typed.",
    "rise": "Rise",
    "reynolds_number": "Reynolds number",
    "fluid_flowing_at_v": "A fluid flowing at v in a pipe of width d: its Reynolds number, and whether it flows smoothly in layers, laminar, or churns, turbulent, its speed across the pipe drawn; along a length L, the pressure it loses to friction, by Darcy and Weisbach, f from Colebrook's equation of the pipe's roughness ε, and the power to pump it. Water at 20 °C unless typed, 998 kg/m³ and μ 1.002e-3 Pa·s; air is 1.204 and 1.81e-5. Steel pipe is some 0.045 mm rough, plastic 0.0015.",
    "mm": "ε, mm",
    "stokes_law": "Stokes' law",
    "small_ball_of_radius": "A small ball of radius r and density ρ<sub>s</sub> falling slowly through a fluid, as a bead through honey, sand through water or a droplet of mist through air: the speed it falls no faster than, below 0 if it rises, the drag then, and its Reynolds number, below about 1 for the law to hold; its forces drawn. Water at 20 °C unless typed, 998 kg/m³ and μ 1.002e-3 Pa·s; glycerine is 1260 and 1.41, honey some 1420 and 10, air 1.204 and 1.81e-5. Steel is 7800, glass 2500.",
    "mass_and_energy": "Mass and energy",
    "energy_in_mass_by": "The energy in a mass, by Einstein, or the mass of an energy: in joules, electronvolts, kilowatt-hours and tonnes of TNT.",
    "m_kg": "m, kg",
    "binding_energy": "Binding energy",
    "energy_holding_nucleus_of": "The energy holding a nucleus of Z protons and A nucleons together, of the mass of its atom in u: its mass defect, and its binding energy, in all and of each nucleon, highest near iron, drawn. Helium-4 is 4.002602 u, iron-56 55.934936, uranium-235 235.043928.",
    "q_value": "Q-value",
    "energy_nuclear_reaction_or": "The energy a nuclear reaction or a decay gives off, or takes in, of the masses of the atoms before and after, in u, + between them: above 0, it gives energy off. Of one atom decaying into two, how they share it, the lighter faster. Uranium-238 is 238.050788 u, thorium-234 234.043601, helium-4 4.002602, hydrogen-2 2.014102, hydrogen-3 3.016049, the neutron 1.008665.",
    "before": "Before",
    "after": "After",
    "photoelectric_effect": "Photoelectric effect",
    "light_on_metal_of": "Light on a metal of work function φ: whether it knocks electrons out, how fast they come, the voltage that stops them, and the light it takes. φ of caesium is about 2.1 eV, sodium 2.3, zinc 4.3, copper 4.7.",
    "ev": "φ, eV",
    "de_broglie_wavelength": "de Broglie wavelength",
    "wavelength_of_particle_of": "The wavelength of a particle, of its speed or of its kinetic energy in eV: of an electron, a proton, a neutron or a mass typed. Near the speed of light, worked out by relativity.",
    "e_k_ev": "E<sub>k</sub>, eV",
    "ek": "Ek",
    "uncertainty_principle": "Uncertainty principle",
    "heisenberg_s_of_how": "Heisenberg's: of how well the place of a particle is known, how badly its momentum and speed can be, and the energy it must have at least; or the other way; or of energy and time, as how long a state lasts and how wide its line is.",
    "p_kg_m_s": "Δp, kg·m/s",
    "e_ev_2": "ΔE, eV",
    "particle_in_box": "Particle in a box",
    "particle_held_in_box": "A particle held in a box of width L, its walls too high to leave: the energy of its level n, the step to the next, and the light it gives falling to the level below. An electron in a box of 1 nm, as in a dye or a quantum dot.",
    "compton_scattering": "Compton scattering",
    "x_ray_or_gamma": "An X-ray or gamma photon bouncing off an electron at an angle θ: its wavelength and energy after, and the energy the electron takes. The shift is the same whatever the light: it shows on X-rays, of short wavelengths.",
    "e_kev": "E, keV",
    "pm": "λ, pm",
    "quantum_tunnelling": "Quantum tunnelling",
    "chance_particle_goes_through": "The chance a particle goes through a barrier higher than its energy, as it never could by Newton: of its energy E, the barrier's height V and width L, worked out in full. Above the barrier, the chance it is not reflected.",
    "v_ev": "V, eV",
    "relativity": "Relativity",
    "moving_at_speed_by": "Moving at a speed, by Einstein's special relativity: how much slower its clocks go and how much shorter it is, as seen standing still; and of a mass, its momentum and kinetic energy, against Newton's.",
    "of_c": "Of c",
    "hydrogen_and_bohr": "Hydrogen and Bohr",
    "light_of_hydrogen_s": "The light of hydrogen's electron falling from the level n₂ to n₁, by Rydberg: its wavelength, frequency, energy, series and colour; and by Bohr's model the energy of each level, the size of its orbit and the electron's speed. Of an ion of one electron, its Z: He⁺ is 2.",
    "radioactive_decay": "Radioactive decay",
