    "graph_fills_page_to": "The graph fills the page, to see more of the curves: all of the window on the website, and in a window of its own beside the calculator in the extension.",
    "graph_small_again_over": "The graph is small again, over the keys.",
    "share_and_save": "Share and save",
    "copy_link_opens_graph": "Copy a link that opens this graph, its curves, sliders, view and settings, for anyone; copy it as a picture, or save it as PNG or SVG, with the function of each curve; or save its table as CSV. Right-click the graph for the same.",
    "undo": "Undo",
    "takes_back_last_change": "Takes back the last change of the graph: what was typed, a curve removed or cleared, a slider, a setting, a point dragged. Not a move or a zoom of the view.",
    "redo": "Redo",
    "does_again_what_undo": "Does again what Undo took back.",
    "add_curve": "Add a curve",
    "box_for_another_function": "A box for another function, in its own color: up to 25 curves.",
    "remove_curve": "Remove the curve",
    "takes_curve_away_ones": "Takes this curve away. The ones below it move up, each with its color.",
    "draw_best_fit": "Draw the best fit",
    "draws_straight_line_nearest": "Draws the straight line nearest these points, by least squares; point at it for its r². Click again for a quadratic, an exponential, a power and a logarithmic fit.",
    "fit_parabola": "Fit a parabola",
