    "hide_curve": "Hide the curve",
    "hides_curve_and_points": "Hides this curve and its points, and leaves it out of the table. What is typed stays. The ▾ beside it, or a right click, picks its color and its line, solid, dashed or dotted, thin or thick, and labels points.",
    "show_curve": "Show the curve",
    "draws_curve_again_beside": "Draws this curve again. The ▾ beside it, or a right click, picks its color and its line, solid, dashed or dotted, thin or thick, and labels points.",
    "color_and_line": "Color and line",
    "color_by_shade_hue": "Its color, by its shade, hue or hex, Auto its own again; its line solid, dashed or dotted, thin, normal or thick; of points, their x and y beside them; and Hide or Show.",
    "insert_t": "Insert t",
