    "graph_settings": "Graph settings",
    "type_where_x_goes": "Type where x goes from and to across the graph, and y up it, and by what step the grid goes, 0.5 or π/2; below, switch the same scale, the grid, minor lines, a polar grid, each axis and its numbers, and arrows, and lock the view; and name the axes. Enter or Esc goes back to the graph.",
    "same_scale": "Same scale",
    "unit_of_x_as": "A unit of x as long as one of y, however the graph is zoomed: a circle is round, and a slope of 1 at 45°. For a curve of an angle in Deg, a radian of x as long as 1 of y; in Rad, the grid of x by numbers and not π, so its squares are square.",
