    "lock_view": "Lock view",
    "dragging_wheel_and_pinch": "Dragging, the wheel and a pinch no longer move the view, and the zoom buttons go: to point at and click the curves without moving them. Points and areas are still dragged, and the view can still be typed.",
    "area_under_curve": "Area under a curve",
    "press_then_drag_along": "Press, then drag along a curve from one x to another: the area between it and the x axis is shaded, above the axis counted up and below it down. Pressed between two curves, the area between them, the upper one less the lower. An end near a root or a crossing goes to it; held at a side, the view slides on for more. It stays pressed for another, until it is pressed again, a double click on the plot, Esc, or a button of the view.",
    "type_start": "Type the start",
