    "statistics": "Statistics",
    "type_or_paste_list": "Type or paste a list of numbers, a column from a spreadsheet as well, for its mean, standard deviation, sum, quartiles, median and more, with a histogram and a box plot. The Pairs tab takes x and y on each line, for the curve of best fit and the correlation; the Tests tab tests hypotheses.",
